insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('bbfd5bfd-d7ab-46e6-a9ef-c10130add4e3', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$figuur 1 en 2 — foto vrije worp en tabel basketbalgegevens$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context1.png$$,
   $$Bij basketbal scoor je door de bal van bovenaf door een metalen ring te gooien waaraan een netje bevestigd is. Rens en Dyon onderzoeken de beweging van de bal bij een vrije worp. Bij een vrije worp probeert de speler de bal door de ring te gooien terwijl hij achter de ''vrijeworplijn'' staat. Zie figuur 1. In figuur 2 staat een tabel met een aantal gegevens over basketbal.

figuur 1: foto van een speler die een vrije worp neemt richting de basketbalring, met de vrijeworplijn aangegeven.

figuur 2 (tabel basketbal):
massa bal: 600 g
diameter bal: 24 cm
hoogte ring: 3,05 m
diameter ring: 45 cm
horizontale afstand van vrijeworplijn tot midden van de ring: 4,6 m$$, 'inline'),
  ('d9545b22-b817-4801-b9ef-b279e29f750a', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$(x,t)- en (y,t)-diagram — betekenis x, y en t=0 (figuren 3a en 3b)$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context2.png$$,
   $$Met behulp van een videometing is de beweging van de bal na de worp geanalyseerd. Je kunt de beweging van de bal beschouwen als een combinatie van een horizontale beweging (in de x-richting) en een verticale beweging (in de y-richting). De videometing levert het (x,t)-diagram en het (y,t)-diagram van de beweging van het middelpunt van de bal. Zie de figuren 3a en 3b. Hierin is x de horizontale afstand vanaf de vrijeworplijn en y de hoogte boven de grond. Op t = 0 s verlaat de bal de hand van de speler.
De grootheid snelheid is een vectorgrootheid, net als de grootheid kracht. Je kunt daarom de grootte van de snelheid op dezelfde manier uit haar componenten berekenen als bij kracht.

figuur 3a: (x,t)-diagram — rechte, stijgende lijn van x ≈ 0,35 m bij t = 0 s tot x ≈ 4,6 m bij t = 1,2 s.
figuur 3b: (y,t)-diagram — kromme die start bij y ≈ 2,3 m bij t = 0 s, stijgt tot een maximum van y ≈ 4,5 m rond t ≈ 0,65 s en daarna weer daalt tot y ≈ 3,1 m bij t = 1,2 s.$$, 'inline'),
  ('3e281655-d49c-4781-bfbc-56dcf569d922', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$uitwerkbijlage vraag 1 — figuur 3a vergroot ((x,t)-diagram)$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context3.png$$,
   $$uitwerkbijlage bij vraag 1: figuur 3a ((x,t)-diagram) vergroot weergegeven, zodat de helling (en dus de snelheidscomponent) nauwkeurig afgelezen kan worden.$$, 'uitwerkbijlage'),
  ('0b9eac86-eaf2-4530-861b-1642b1fa4304', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$uitwerkbijlage vraag 1 — figuur 3b vergroot ((y,t)-diagram)$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context4.png$$,
   $$uitwerkbijlage bij vraag 1: figuur 3b ((y,t)-diagram) vergroot weergegeven, zodat de helling (en dus de snelheidscomponent) nauwkeurig afgelezen kan worden.$$, 'uitwerkbijlage'),
  ('293c24ab-be62-4438-b3ae-f0139d0f56b1', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$figuur 4 — foto''s begin en einde van een vrije worp, snelheid 7,1 m s⁻¹$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context5.png$$,
   $$In figuur 4 zijn foto''s te zien van een andere vrije worp. Op de linker foto is het begin van de worp te zien, waarbij de speler extra spierkracht begint uit te oefenen op de bal om hem een snelheid te geven. Op de rechter foto is het einde van de worp te zien, waarbij de bal net is losgekomen van de hand van de speler. Bij deze vrije worp verlaat de bal de hand met een snelheid van 7,1 m s⁻¹. Figuur 4 is vergroot weergegeven op de uitwerkbijlage.

figuur 4: twee foto''s (begin worp / einde worp) van een speler die een vrije worp neemt, met stippellijnen die de richting bij begin en einde van de worp aangeven.$$, 'inline'),
  ('e089167d-bb6f-4412-b711-44894a2cf9de', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$uitwerkbijlage vraag 2 — figuur 4 vergroot (foto''s begin/einde worp)$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context6.png$$,
   $$uitwerkbijlage bij vraag 2: figuur 4 (de foto''s van begin en einde van de worp) vergroot weergegeven, zodat de verplaatsing van de bal nauwkeurig gemeten kan worden.$$, 'uitwerkbijlage'),
  ('ac5ec3cb-d434-4e4c-9a2d-f4505abc155d', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$figuur 5 — vereenvoudigd model (modelformules en startwaarden)$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context7.png$$,
   $$Om een beter inzicht te krijgen in de beweging van de bal na de worp, ontwerpen Rens en Dyon een vereenvoudigd model. Dit model is weergegeven in figuur 5. Ook hier is t = 0 s het moment dat de bal de hand van de speler verlaat.

figuur 5 (modelformules):
dx = vx · dt
x = x + dx
dvy = g · dt
vy = vy + dvy
dy = vy · dt
y = y + dy
t = t + dt

figuur 5 (startwaarden):
x = 0,35 (m)
y = 2,32 (m)
vx = 4,6 (m s⁻¹)
vy = 5,4 (m s⁻¹)
g = −9,81 (m s⁻²)
t = 0 (s)
dt = 0,0001 (s)

Onder de tabellen staat een stroomdiagram dat schematisch weergeeft hoe x uit vx en dt wordt berekend en hoe y via vy en g wordt bijgewerkt.$$, 'inline'),
  ('24ca6f79-6a19-40b0-b8e5-01a01dcaf7e3', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$figuur 6 — vijf modelresultaten (banen A t/m E) bij variatie van vx en vy$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context8.png$$,
   $$Rens en Dyon laten de computer het model een aantal keren doorrekenen. Rens kiest eerst een aantal keren een andere startwaarde voor vx, zonder die van vy te veranderen. Vervolgens zet hij de waarde van vx terug naar de oorspronkelijke startwaarde. Daarna varieert Dyon een aantal keren de startwaarde van vy, zonder die van vx te veranderen. De resultaten van vijf berekeningen zijn weergegeven in figuur 6.

figuur 6: (x,y)-grafiek met vijf banen, gelabeld A, B, C, D en E, die dicht bij elkaar liggen voor kleine x en uiteenlopen bij grotere x; de banen eindigen in het gebied x ≈ 3,5-4,8 m, y ≈ 2,9-3,9 m.

In het model is ingebouwd dat de berekeningen stoppen als aan twee voorwaarden is voldaan. Deze voorwaarden worden in de instellingen van het programma ingevoerd.$$, 'inline'),
  ('39b02f5c-769b-46f7-97e5-99dc3469124f', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$bij resultaat C in figuur 6 wordt er gescoord$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context9.png$$,
   $$Bij resultaat C in figuur 6 wordt er gescoord.$$, 'inline'),
  ('5f877ec4-c3ba-4b9c-bd4f-0c3e47d6ba89', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$verschuivingen in figuur 6 zijn gevolg van variatie in vx (Rens) of vy (Dyon)$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context10.png$$,
   $$De verschillende resultaten in figuur 6 zijn het gevolg van variaties in de startwaarde van vx door Rens of van variaties in de startwaarde van vy door Dyon. Op de uitwerkbijlage staat een tabel.$$, 'inline'),
  ('4a1605f2-3f8a-42c3-8ac5-09a92e63743f', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', $$uitwerkbijlage vraag 5 — tabel resultaten A, B, D, E (variatie vx of vy)$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-context11.png$$,
   $$uitwerkbijlage bij vraag 5: tabel met de resultaten A, B, D en E uit figuur 6, waarbij per resultaat omcirkeld moet worden of de verschuiving ten opzichte van resultaat C een gevolg is van een variatie in de startwaarde van vx of van vy, met ruimte voor een toelichting.

vraagtekst op de uitwerkbijlage: Is resultaat A, B, D, E een gevolg van een variatie in de startwaarde van vx of van vy, vergeleken met resultaat C? Omcirkel steeds het juiste antwoord.$$, 'uitwerkbijlage'),
  ('dc48aed7-e654-43a5-869a-ccbb63274ca2', '428341aa-b945-4978-b844-80634e0a4622', $$figuur 1 en 2 — quantum-dot en kleur afhankelijk van de grootte$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context1.png$$,
   $$In het scherm van een Qled-tv valt violet licht afkomstig uit leds op een laagje met quantum-dots. Quantum-dots zijn kleine bolletjes met afmetingen variërend van 1 tot 20 nm, gemaakt van een speciaal materiaal. In figuur 1 staat een artist''''s impression van één quantum-dot (opgebouwd uit atomen). De quantum-dots absorberen het violette licht waarmee ze bestraald worden en zenden daarna zelf licht uit met een andere kleur dan violet.
Voor de werking van een Qled-tv zijn quantum-dots nodig die blauw, groen of rood licht uitzenden. De kleur van het uitgezonden licht hangt af van de grootte van de quantum-dot. Zie figuur 2.

figuur 1: artist''''s impression van één quantum-dot, opgebouwd uit atomen.
figuur 2: schema waarin invallend violet licht op quantum-dots van verschillende grootte valt en waarbij de kleinste quantum-dot blauw licht uitzendt, de middelste groen en de grootste rood.$$, 'inline'),
  ('64b2b52e-a7b1-4a92-9c4e-b1b1503c0ec0', '428341aa-b945-4978-b844-80634e0a4622', $$quantum-dots in een Qled-tv worden met violet licht bestraald$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context2.png$$,
   $$De quantum-dots in een Qled-tv worden met violet licht bestraald.$$, 'inline'),
  ('c4f3d2a4-36f1-402b-a754-abca6d120dda', '428341aa-b945-4978-b844-80634e0a4622', $$figuur 3 — energiebandenschema van een halfgeleider (bandgap Egap)$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context3.png$$,
   $$Halfgeleider
Een quantum-dot is gemaakt van een zogenaamd halfgeleidermateriaal. In een halfgeleider kan een elektron slechts in banden van zeer dicht bij elkaar gelegen energieniveaus bestaan. Voor de werking van een quantum-dot zijn slechts twee van deze energiebanden van belang: de valentieband en de geleidingsband. Daartussen zit bij een halfgeleider een energieverschil, de zogeheten bandgap Egap. Zie figuur 3.

figuur 3: energiebandenschema van een halfgeleider met de valentieband onderaan (met een gat), de bandgap Egap ertussen, en de geleidingsband bovenaan (met een elektron).$$, 'inline'),
  ('5b5956f4-48d7-4d34-8de4-aec146c83cbf', '428341aa-b945-4978-b844-80634e0a4622', $$vorming van een elektron-gatpaar door absorptie van een foton$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context4.png$$,
   $$Als een foton geabsorbeerd wordt maakt het één elektron vrij uit het atoomrooster. De energie van dat foton moet daarvoor groot genoeg zijn. Het elektron gaat dan van een energieniveau in de valentieband naar een energieniveau in de geleidingsband. Dit betekent dat het loskomt uit het atoomrooster van de halfgeleider. Het achterblijvende gat in de valentieband kan worden opgevat als een positief deeltje dat door het rooster beweegt. Het aangeslagen elektron en het achterblijvende gat worden samen een elektron-gatpaar genoemd.$$, 'inline'),
  ('c35289ba-4fcc-4d46-9780-3e45e71aec74', '428341aa-b945-4978-b844-80634e0a4622', $$figuur 4 — tabel bandgap-waarden van halfgeleiders en fotonenergie violet licht$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context5.png$$,
   $$In figuur 4 is van enkele halfgeleiders de bandgap gegeven.

figuur 4 (tabel):
Si: Egap = 1,12 eV
CdSe: Egap = 1,74 eV
Si3N4: Egap = 5,00 eV
GaAs: Egap = 1,43 eV
GaP: Egap = 2,26 eV

Neem aan dat de fotonenergie van het gebruikte violette licht tussen 2,75 eV en 3,10 eV ligt.$$, 'inline'),
  ('71be4413-4384-45d9-8186-6200c2842358', '428341aa-b945-4978-b844-80634e0a4622', $$effectieve massa''s van elektron en gat (meff, elektron = 0,13 me; meff, gat = 0,45 me)$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context6.png$$,
   $$In goede benadering kunnen elektron en gat van een elektron-gatpaar worden opgevat als vrije deeltjes. Als gevolg van de invloed van het atoomrooster op hun beweging zijn de massa''s van deze deeltjes echter niet gelijk aan de elektronmassa me. Ze krijgen beide een zogenaamde effectieve massa meff. Voor de halfgeleider die wordt gebruikt in een Qled-tv geldt: meff, elektron = 0,13 me en meff, gat = 0,45 me.$$, 'inline'),
  ('64eb9ae2-dc99-4921-8ec5-2131dc927624', '428341aa-b945-4978-b844-80634e0a4622', $$formule (1): λB = h / √(2·meff·Ek) — debroglie-golflengte$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context7.png$$,
   $$Voor de debroglie-golflengte λB van het elektron of het gat geldt:

λB = h / √(2·meff·Ek)   (1)

Hierin is:
− h de constante van Planck
− meff de effectieve massa
− Ek de kinetische energie$$, 'inline'),
  ('8782cc50-01a1-43c0-9d42-bccc13ce9fc7', '428341aa-b945-4978-b844-80634e0a4622', $$kinetische energie van het elektron is 1 eV$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context8.png$$,
   $$Neem voor de kinetische energie van het elektron 1 eV.$$, 'inline'),
  ('9574ed95-08e3-4834-9765-3bd6b6e479b8', '428341aa-b945-4978-b844-80634e0a4622', $$figuur 5 — gequantiseerde energieniveaus in een quantum-dot (Enul)$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context9.png$$,
   $$Quantum-dot
In een oneindig grote halfgeleider kan de energie van het elektron-gatpaar Eeg elke waarde hebben boven de bandgap. In een quantum-dot wordt het elektron-gatpaar in een kleine ruimte opgesloten. Daardoor worden de energieniveaus van het elektron-gatpaar gequantiseerd. Hoe kleiner de ruimte, hoe groter de afstand tussen de afzonderlijke energieniveaus. Zie figuur 5.

figuur 5: energieniveauschema met links een oneindig grote halfgeleider (continuüm van energieniveaus boven Egap) en rechts twee quantum-dots, een grote en een kleine, elk met discrete energieniveaus op afstand Enul boven Egap; bij terugval van het elektron in het gat wordt een foton uitgezonden.$$, 'inline'),
  ('4cb5d093-42df-4632-b0b2-b3a59e1bda62', '428341aa-b945-4978-b844-80634e0a4622', $$nulpuntsenergie Enul = Enul,elektron + Enul,gat (energieput met oneindig hoge wanden)$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context10.png$$,
   $$In een vereenvoudigd model kan de quantum-dot beschouwd worden als een energieput met oneindig hoge wanden. Voor de nulpuntsenergie van een deeltje in deze energieput kan worden uitgegaan van een eendimensionale put, waarvan de lengte L gelijk is aan de straal R van de quantum-dot. De energie Enul in figuur 5 is de som van de nulpuntsenergieën van elektron en gat in deze energieput. Dus

Enul = Enul, elektron + Enul, gat

Na zijn ontstaan komt het elektron-gatpaar door wisselwerking met het atoomrooster uiteindelijk in de grondtoestand van de energieput terecht. Als het elektron vervolgens terugvalt in het gat zendt de quantum-dot een foton uit. In figuur 5 is dit schematisch weergegeven.$$, 'inline'),
  ('bd33fd12-3756-4c18-9dcb-6fe98d8b1037', '428341aa-b945-4978-b844-80634e0a4622', $$formule (2): Ef = Egap + C/R² — energie van het uitgezonden foton$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context11.png$$,
   $$Voor de energie van het uitgezonden foton Ef geldt:

Ef = Egap + C/R²   (2)

Hierin is C een constante met de eenheid J m², die afhangt van meff, elektron, meff, gat en h.$$, 'inline'),
  ('143f0646-26e3-45f2-933a-0190508273cd', '428341aa-b945-4978-b844-80634e0a4622', $$figuur 6 — gelineariseerde grafiek Ef tegen R⁻² (groen licht, 534 nm)$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context12.png$$,
   $$Een fabrikant van Qled-tv''s wil quantum-dots selecteren die na bestraling met het violette licht groen licht uitzenden met een golflengte van 534 nm. Door een coördinatentransformatie toe te passen, is van formule (2) een lineaire grafiek gemaakt. Zie figuur 6.

figuur 6: rechte, stijgende lijn van Ef (eV) tegen R⁻² (nm⁻²), lopend van ongeveer (0,08; 2,05) tot (0,44; 3,35).$$, 'inline'),
  ('e0d03606-284d-490f-b6fa-e3ec05082a2a', '428341aa-b945-4978-b844-80634e0a4622', $$uitwerkbijlage vraag 7 — tabel geschikt/ongeschikt per halfgeleider$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-context13.png$$,
   $$uitwerkbijlage bij vraag 7: dezelfde tabel met halfgeleiders en hun bandgap Egap als in figuur 4, met bij elke halfgeleider de keuze ''geschikt'' of ''ongeschikt'' om te omcirkelen, en ruimte voor een toelichting.

vraagtekst op de uitwerkbijlage: Geef van elke halfgeleider aan of deze op grond van de bandgap geschikt is voor gebruik in een Qled-tv. Omcirkel steeds het juiste antwoord.$$, 'uitwerkbijlage'),
  ('1f18d0fe-9c4c-465c-95a3-14677ecbb115', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$figuur 1 — opstelling met oven, temperatuursensor en stralingsdetector$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context1.png$$,
   $$Tess en Fem voeren een practicum uit over warmtestraling waarmee ze de constante van Stefan-Boltzmann gaan bepalen. Ze gebruiken de opstelling zoals weergegeven in figuur 1.

figuur 1: foto van de practicumopstelling met een oven, een temperatuursensor en een stralingsdetector.$$, 'inline'),
  ('66156b7d-3fe3-42d9-b5cd-153d832df6a0', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$figuur 2 — verwarmingselement (constantaandraad, diameter en lengte, spanning 120 V)$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context2.png$$,
   $$In de opstelling zie je een oven. In de oven is een verwarmingselement aangesloten op gelijkspanning. Zie figuur 2.
Het verwarmingselement bestaat uit een draad van constantaan met een diameter van 4,0·10⁻⁵ m en een lengte van 0,35 m. De spanning wordt ingesteld op 120 V.

figuur 2: schakelschema van een gelijkspanningsbron in serie met het verwarmingselement (weerstand).$$, 'inline'),
  ('da6a6bc8-9acd-45de-b4b4-facbe9f310b3', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$formule (1): ρT = ρ0(1 + α(T − T0)) — soortelijke weerstand en temperatuur$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context3.png$$,
   $$De soortelijke weerstand van metaal is afhankelijk van de temperatuur volgens de formule:

ρT = ρ0(1 + α(T − T0))   (1)

Hierin is:
− ρT de soortelijke weerstand bij temperatuur T in Ω m
− ρ0 de soortelijke weerstand bij kamertemperatuur in Ω m
− α de weerstandstemperatuurcoëfficiënt in K⁻¹ (te vinden in het informatieboek)
− T de temperatuur in K
− T0 de kamertemperatuur: 293 K$$, 'inline'),
  ('4b7befd6-f7ef-4943-bcb3-c8067bad4847', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$discussie Tess/Fem: verandering soortelijke weerstand van 20 °C naar 300 °C kleiner of groter dan 5%$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context4.png$$,
   $$Het elektrisch vermogen dat het verwarmingselement opneemt, is omgekeerd evenredig met de soortelijke weerstand ρT. Daardoor verandert dit vermogen als de temperatuur toeneemt.
Tess en Fem discussiëren over de grootte van de verandering van de soortelijke weerstand als de temperatuur toeneemt van 20 °C naar 300 °C.
Tess beweert dat deze verandering kleiner dan 5% is.
Fem beweert dat deze verandering groter dan 5% is.$$, 'inline'),
  ('a5e7c53c-9f4f-437b-9d66-62489fb4cc58', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$figuur 3 — bovenaanzicht opstelling, stralingsintensiteit P/A als functie van temperatuur$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context5.png$$,
   $$In figuur 3 is de opstelling schematisch in bovenaanzicht getekend.

figuur 3: schematisch bovenaanzicht met op één lijn de temperatuursensor, de oven en de stralingsdetector.

De temperatuur van de oven kan gevarieerd worden. Midden in de oven is een temperatuursensor geplaatst. De stralingsdetector staat vóór dit geheel. De opstelling is zo afgesteld dat de stralingsdetector de uitgezonden stralingsintensiteit P/A in W m⁻² van de oven meet als functie van de temperatuur.$$, 'inline'),
  ('02f44558-d98d-4ae3-98fd-7a6ffc2472c4', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$figuur 4 — grafiek van P/A tegen T⁴$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context6.png$$,
   $$Tess en Fem maken van hun resultaten een grafiek waarin ze P/A uitzetten tegen T⁴. De grafiek staat in figuur 4. Figuur 4 staat ook op de uitwerkbijlage.

figuur 4: puntenwolk van P/A (×10³ W m⁻²) tegen T⁴ (×10¹⁰ K⁴), een vrijwel rechte, stijgende reeks punten van ongeveer (3; 1,7) tot (18; 10,6).$$, 'inline'),
  ('1912b58e-1d0e-4680-b3e9-e1e1ed74118d', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$maximale oventemperatuur 383 °C$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context7.png$$,
   $$De oven bereikt uiteindelijk een maximale temperatuur van 383 °C.$$, 'inline'),
  ('0d953f64-78cf-4947-bc43-1fad1e8af12e', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$figuur 5 — meetresultaten stralingsintensiteit I tegen afstand x$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context8.png$$,
   $$Tess en Fem gaan een ander experiment doen: ze houden de temperatuur van de oven constant, maar ze variëren de afstand van de stralingsdetector tot de oven. Ze willen hiermee controleren of in deze situatie de kwadratenwet geldt.
Ze meten hierbij de stralingsintensiteit I die op de stralingsdetector valt als functie van de afstand. Hun meetresultaten staan weergegeven in figuur 5.

figuur 5 (tabel):
x = 40 cm: I = 4810 W m⁻²
x = 50 cm: I = 1740 W m⁻²
x = 60 cm: I = 980 W m⁻²
x = 70 cm: I = 620 W m⁻²$$, 'inline'),
  ('9662fd2b-99fa-405a-9851-d59ecde47266', '3998d952-b8eb-4848-a697-6bb41983d0e1', $$uitwerkbijlage vraag 13 — figuur 4 vergroot (P/A tegen T⁴)$$,
   $$natuurkunde-vwo-2022-ii-practicum-warmtestraling-context9.png$$,
   $$uitwerkbijlage bij vraag 13: figuur 4 (de grafiek van P/A tegen T⁴) vergroot weergegeven, zodat de helling van de rechte lijn nauwkeurig bepaald kan worden.$$, 'uitwerkbijlage'),
  ('a041cba1-3a2b-4672-986c-c52b1fc0d755', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$bron voor β⁻-deeltjes, vervalproduct Yttrium-90, geen gammastraling bij dit verval$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context1.png$$,
   $$Niels voert een practicum uit waarin hij het gedrag van bètadeeltjes in de lucht onderzoekt. Hij gebruikt een radioactief preparaat als bron voor β⁻-deeltjes. Neem aan dat deze bron bij de start van het practicum maar één isotoop bevat. Tijdens het vervalproces van deze isotoop ontstaat Yttrium-90 als vervalproduct. Bij dit vervalproces komt geen gammastraling vrij.$$, 'inline'),
  ('8a3a41a5-58b2-4bd5-88c4-76f1405e7b94', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$toch komt er gammastraling vrij uit de bron$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context2.png$$,
   $$Toch komt er gammastraling vrij uit de bron.$$, 'inline'),
  ('c12bfde0-b7f6-45fc-85a0-149eb0709d26', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$figuur 1 — opstelling met bron, loden blok en GM-sensor$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context3.png$$,
   $$Niels bouwt de opstelling zoals weergegeven in figuur 1. Een loden blok is zó geplaatst dat straling niet in een rechte lijn van de bron naar de Geiger-Müller-sensor (GM-sensor) kan bewegen.

figuur 1: schematische tekening van de opstelling met de bron, het loden blok en de GM-sensor, waarbij het loden blok het rechtstreekse zicht van de bron op de GM-sensor blokkeert.$$, 'inline'),
  ('92220cc1-e822-46d4-b71b-44e94d2b5865', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$figuur 2 — hoefijzermagneet buigt bètadeeltjes af naar de GM-sensor (polen L en R)$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context4.png$$,
   $$Verwaarloos bij het vervolg van deze opgave de eventuele invloed van de gammastraling op de metingen.
Met behulp van een sterke hoefijzermagneet wil Niels bètadeeltjes om het blok heen afbuigen richting de GM-sensor. Dit is weergegeven in figuur 2.

figuur 2: schematische tekening van de opstelling met de hoefijzermagneet (polen aangeduid met L en R), waarbij een gestippelde, gebogen baan de afbuiging van een bètadeeltje van de bron naar de GM-sensor aangeeft.$$, 'inline'),
  ('7c6f3258-e7da-4cd5-91d2-b51fc9a90e7a', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$formule (1): v = Bqr/m — snelheid van een bètadeeltje in een magnetisch veld$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context5.png$$,
   $$Niels wil met zijn opstelling de snelheid van de bètadeeltjes bepalen. Hij neemt aan dat in deze situatie de zwaartekracht op de bètadeeltjes verwaarloosd mag worden. Verder neemt hij aan dat het magneetveld homogeen is en dat de bètadeeltjes dus een cirkelbeweging uitvoeren. Met behulp van formules uit het informatieboek leidt Niels de volgende formule af voor de snelheid v van een bètadeeltje:

v = Bqr/m   (1)

Hierin is:
− B de sterkte van het magnetisch veld
− q de lading van het bètadeeltje
− r de straal van de cirkelbaan
− m de massa van het bètadeeltje$$, 'inline'),
  ('45506ea4-2561-4b9d-a6fe-e12ea30adf86', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$relativistische effecten spelen een rol boven 10% van de lichtsnelheid$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context6.png$$,
   $$Wanneer de snelheid van een deeltje groter is dan 10% van de lichtsnelheid, moet er rekening gehouden worden met zogenaamde relativistische effecten.$$, 'inline'),
  ('330a034f-5aed-43ce-b5d9-3672b143c905', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$magnetisch veld 0,1 T, gemiddelde straal cirkelbaan 0,20 m$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context7.png$$,
   $$Het magnetisch veld tussen de polen is 0,1 T. Niels bepaalt de gemiddelde straal van de cirkelbaan van de bètadeeltjes die op de GM-sensor vallen en vindt 0,20 m.$$, 'inline'),
  ('945b942b-25a3-49cf-b72e-ac61a1e2cc5c', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$figuur 3 — drie meetreeksen met de GM-sensor (tellen per minuut)$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context8.png$$,
   $$Voordat Niels de bron en de magneet in de opstelling plaatst, doet hij eerst driemaal een meting met de GM-sensor (figuur 3, reeks 1). Vervolgens plaatst Niels de bron in de opstelling zonder magneet en doet hij weer drie metingen (reeks 2). Ten slotte plaatst Niels ook de hoefijzermagneet in de opstelling en doet hij nogmaals drie metingen (reeks 3).

figuur 3 (tabel, tellen per minuut):
reeks 1 (zonder bron, zonder magneet): 34, 27, 31
reeks 2 (met bron, zonder magneet): 160, 155, 165
reeks 3 (met bron, met magneet): 479, 497, 486$$, 'inline'),
  ('31cbe36b-fbd9-404a-b8ac-a2234d0d191a', '4dd9367c-24c3-4c30-aa79-f890ca745d7c', $$in de tweede meetreeks worden bètadeeltjes nog niet afgebogen, toch meer straling$$,
   $$natuurkunde-vwo-2022-ii-om-het-hoekje-context9.png$$,
   $$In de tweede meetreeks worden de bètadeeltjes nog niet afgebogen door de magneet. Toch meet de GM-sensor al meer straling dan in de eerste meetreeks.$$, 'inline'),
  ('681d31fb-2e66-455a-88d1-cd870d1f2236', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$figuur 1 — fluit met twee gesloten uiteinden en drie gaten, kamertemperatuur 20 °C$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context1.png$$,
   $$In figuur 1 zie je een speciale fluit met twee gesloten uiteinden en slechts drie gaten. We gaan uit van een kamertemperatuur van 20 °C.

figuur 1: foto van de speciale fluit met drie gaten.$$, 'inline'),
  ('a787f98e-e0b0-4d44-b7d9-17b826e7eee0', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$figuur 2 — het middelste gat wordt gebruikt om aan te blazen$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context2.png$$,
   $$Het middelste gat wordt gebruikt om de fluit aan te blazen. Zie figuur 2. De andere twee gaten kunnen met een vinger afgesloten worden.

figuur 2: foto van iemand die de fluit aanblaast via het middelste gat.$$, 'inline'),
  ('dd5405c5-1fb1-4762-a15e-c24c7759de62', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$Daniël en Jonathan onderzoeken de toonvorming in de fluit$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context3.png$$,
   $$Daniël en Jonathan gaan onderzoeken hoe de toonvorming in de fluit plaatsvindt.$$, 'inline'),
  ('071d6434-430c-4e66-99bf-dd6ded38f7c5', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$figuur 3a en 3b — toon I en toon II met één gat gesloten$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context4.png$$,
   $$Op de fluit kun je twee tonen spelen met één gat gesloten: toon I en toon II. In figuur 3a en in figuur 3b zijn de twee mogelijkheden om een toon te spelen met één gat gesloten schematisch weergegeven. Een wit bolletje betekent een geopend gat en een zwart bolletje een gat dat is gesloten met een vinger. De fluit wordt aangeblazen door het middelste gat, dat is aangegeven met grijs.

figuur 3a (toon I): van links naar rechts een zwart (gesloten) gat, het grijze aanblaasgat, en een wit (open) gat; onder het gesloten gat staat de letter K (knoop).
figuur 3b (toon II): van links naar rechts een wit (open) gat, het grijze aanblaasgat, en een zwart (gesloten) gat; onder het gesloten gat staat de letter K (knoop).$$, 'inline'),
  ('10f979e6-bbc0-44ef-9d22-5f4e7bdcfddf', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$model van de staande golf: knoop bij gesloten gat, buik bij open gat; frequentie toon I = 6,0·10² Hz$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context5.png$$,
   $$Volgens het model van de staande golven ontstaat er bij het uiteinde aan de kant van het gesloten gat een knoop (K) en ergens in de buurt van het open gat een buik (B). De plaats van de knoop bij toon I en toon II is weergegeven met een letter K. In beide gevallen is sprake van de grondtoon.
Op de uitwerkbijlage staat figuur 3a nogmaals weergegeven. De lengte van de afbeelding van de fluit is precies de helft van de werkelijke lengte.
De frequentie van toon I is 6,0·10² Hz.$$, 'inline'),
  ('bee5ab2a-1bc0-4e73-b714-d3e0a175f4e1', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$fluit aangeblazen met beide andere gaten open geeft een veel hogere toon$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context6.png$$,
   $$Daniël blaast de fluit aan door het middelste gat, met beide andere gaten open. Jonathan ontdekt dat de toon die daardoor ontstaat veel hoger is dan toon I en II. Op de uitwerkbijlage is de fluit in deze situatie schematisch weergegeven.$$, 'inline'),
  ('deca20df-861c-44f8-ae41-516b72c9b854', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$lucht in de fluit heeft door langer blazen een hogere temperatuur gekregen$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context7.png$$,
   $$Daniël en Jonathan hebben al een tijdje op de fluit geblazen, waardoor de lucht in de fluit een hogere temperatuur heeft gekregen.$$, 'inline'),
  ('9fba3b6f-9731-4561-a195-1dd0b1dc8b0a', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$uitwerkbijlage vraag 23 — figuur 3a met tekenruimte voor de buik (B)$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context8.png$$,
   $$uitwerkbijlage bij vraag 23: figuur 3a (toon I, met de knoop K bij het gesloten gat) nogmaals weergegeven, met ruimte om de plaats van de buik (B) in te tekenen.$$, 'uitwerkbijlage'),
  ('2587b50e-c121-4128-9c09-3b2b34ccb74e', 'cbe470ac-e596-4b03-b9c4-c674687d29a3', $$uitwerkbijlage vraag 24 — fluit met beide gaten open, stippellijnen geven het in te vullen gebied aan$$,
   $$natuurkunde-vwo-2022-ii-speciale-fluit-context9.png$$,
   $$uitwerkbijlage bij vraag 24: schematische weergave van de fluit met beide andere gaten open, met twee stippellijnen die het gebied aangeven waarin de kandidaat een mogelijke ligging van knopen (K) en buiken (B) moet intekenen.$$, 'uitwerkbijlage');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('628af4c9-71d2-48ec-a6fa-bcc417923609', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', 1,
   '[{"domain": "Beweging en wisselwerking", "subdomain": "Kracht en beweging"}]'::jsonb,
   '["snelheid uit componenten", "(x,t)-diagram", "(y,t)-diagram", "vectorgrootheid", "helling van een diagram", "significante cijfers"]'::jsonb,
   $$Bepalen van de grootte van de snelheid waarmee de bal de hand van de speler verlaat, uit de helling van een (x,t)- en een (y,t)-diagram$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-vraag1.png$$, $$Figuur 3a en figuur 3b staan vergroot weergegeven op de uitwerkbijlage.
Bepaal met behulp van de figuren op de uitwerkbijlage de grootte van de snelheid op het moment dat de bal de hand van de speler verlaat. Noteer je antwoord in twee significante cijfers.$$, array['d9545b22-b817-4801-b9ef-b279e29f750a','3e281655-d49c-4781-bfbc-56dcf569d922','0b9eac86-eaf2-4530-861b-1642b1fa4304']::uuid[]),
  ('4bdfd4d8-eb68-43be-9f8d-a89fbbd3f497', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', 2,
   '[{"domain": "Beweging en wisselwerking", "subdomain": "Kracht en beweging"}]'::jsonb,
   '["verplaatsing meten", "resulterende kracht", "impulsverandering", "gemiddelde kracht", "tweede wet van Newton"]'::jsonb,
   $$Bepalen van de verplaatsing van de bal tijdens de worp uit foto''s en berekenen van de gemiddelde resulterende kracht op de bal$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-vraag2.png$$, $$Voer de volgende opdrachten uit:
− Bepaal met behulp van de foto''s op de uitwerkbijlage en figuur 2 de verplaatsing van de bal tijdens de worp. Noteer je antwoord in twee significante cijfers.
− Bereken hiermee het gemiddelde van de resulterende kracht op de bal tijdens de worp.$$, array['bbfd5bfd-d7ab-46e6-a9ef-c10130add4e3','293c24ab-be62-4438-b3ae-f0139d0f56b1','e089167d-bb6f-4412-b711-44894a2cf9de']::uuid[]),
  ('e0c7cc85-84d7-487a-ae2a-ed259610b1b3', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', 3,
   '[{"domain": "Natuurwetten en modellen", "subdomain": "Natuurwetten en modellen"}]'::jsonb,
   '["numeriek model", "stopvoorwaarden", "computermodel", "grafiek aflezen", "modelformules"]'::jsonb,
   $$Bepalen van de twee voorwaarden waarbij een numeriek bewegingsmodel stopt met rekenen, op basis van de getoonde grafiek$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-vraag3.png$$, $$Geef de twee voorwaarden zodat het model stopt zoals in figuur 6 is weergegeven.$$, array['bbfd5bfd-d7ab-46e6-a9ef-c10130add4e3','24ca6f79-6a19-40b0-b8e5-01a01dcaf7e3']::uuid[]),
  ('a085ddcd-f363-4f1e-a288-2c306d850d4c', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', 4,
   '[{"domain": "Natuurwetten en modellen", "subdomain": "Natuurwetten en modellen"}]'::jsonb,
   '["model toetsen aan werkelijkheid", "ring afmetingen", "baan van de bal", "grafiek combineren met gegevens"]'::jsonb,
   $$Verklaren aan de hand van het modelresultaat en de afmetingen van ring en bal waarom bij resultaat C daadwerkelijk gescoord wordt$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-vraag4.png$$, $$Leg uit hoe dat blijkt uit figuur 6 in combinatie met figuur 2.$$, array['bbfd5bfd-d7ab-46e6-a9ef-c10130add4e3','24ca6f79-6a19-40b0-b8e5-01a01dcaf7e3','39b02f5c-769b-46f7-97e5-99dc3469124f']::uuid[]),
  ('4c858d8b-2a15-4e7c-bf03-2c2ff854c010', 'b08370ce-8b18-4c7c-b9fd-41c706fadad0', 5,
   '[{"domain": "Natuurwetten en modellen", "subdomain": "Natuurwetten en modellen"}]'::jsonb,
   '["startwaarden variëren", "numeriek model", "gevoeligheid voor parameters", "grafiek interpreteren"]'::jsonb,
   $$Toekennen van de verschuivingen in de modelresultaten A, B, D en E aan een variatie in de startwaarde van vx of van vy$$,
   $$natuurkunde-vwo-2022-ii-vrije-worp-bij-basketbal-vraag5.png$$, $$Geef in de tabel op de uitwerkbijlage aan voor de resultaten A, B, D en E of de verschuiving ten opzichte van resultaat C een gevolg is van een variatie in de startwaarde van vx of van een variatie in de startwaarde van vy. Licht je antwoord toe.$$, array['24ca6f79-6a19-40b0-b8e5-01a01dcaf7e3','5f877ec4-c3ba-4b9c-bd4f-0c3e47d6ba89','4a1605f2-3f8a-42c3-8ac5-09a92e63743f']::uuid[]),
  ('ab9bf61f-ee89-4cab-b62d-d36a6bd8f0cc', '428341aa-b945-4978-b844-80634e0a4622', 6,
   '[{"domain": "Quantumwereld en relativiteit", "subdomain": "Quantumwereld"}]'::jsonb,
   '["bandgap", "fotonenergie", "halfgeleider", "absorptie van licht", "zichtbaar spectrum", "quantum-dot"]'::jsonb,
   $$Verklaren waarom violet licht gebruikt wordt om de quantum-dots in een Qled-tv aan te slaan$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-vraag6.png$$, $$Leg uit waarom gekozen is voor violet licht in plaats van een andere kleur uit het zichtbare spectrum.$$, array['dc48aed7-e654-43a5-869a-ccbb63274ca2','64b2b52e-a7b1-4a92-9c4e-b1b1503c0ec0','c4f3d2a4-36f1-402b-a754-abca6d120dda']::uuid[]),
  ('b142a54c-4aa7-4ee3-a3dd-b4c10a65256a', '428341aa-b945-4978-b844-80634e0a4622', 7,
   '[{"domain": "Quantumwereld en relativiteit", "subdomain": "Quantumwereld"}]'::jsonb,
   '["bandgap", "fotonenergie", "geschiktheid halfgeleider", "energieniveau", "tabel invullen"]'::jsonb,
   $$Bepalen welke halfgeleiders geschikt zijn voor gebruik in een Qled-tv op basis van hun bandgap en de fotonenergie van violet licht$$,
   $$natuurkunde-vwo-2022-ii-qled-tv-vraag7.png$$, $$Geef in de tabel op de uitwerkbijlage voor elke halfgeleider aan of deze op grond van de bandgap geschikt is voor gebruik in een Qled-tv. Licht je antwoord toe.$$, array['c4f3d2a4-36f1-402b-a754-abca6d120dda','c35289ba-4fcc-4d46-9780-3e45e71aec74','e0d03606-284d-490f-b6fa-e3ec05082a2a']::uuid[]),
  ('3363811d-1c52-479b-9e22-76bddc1a3c70', '428341aa-b945-4978-b844-80634e0a4622', 8,
   '[{"domain": "Quantumwereld en relativiteit", "subdomain": "Quantumwereld"}]'::jsonb,
   '["debroglie-golflengte", "effectieve massa", "kinetische energie", "impuls", "formule afleiden"]'::jsonb,
   $$Afleiden van de debroglie-golflengteformule en berekenen van de golflengte van een elektron in een quantum-dot$$,
